import 'package:flutter/material.dart';
import '../../data/models/dashboard_chart_model.dart';
class DashboardChartCard extends StatelessWidget { const DashboardChartCard({required this.title, required this.data, required this.valueBuilder, super.key}); final String title; final List<DashboardChartModel> data; final double Function(DashboardChartModel item) valueBuilder; @override Widget build(BuildContext context) { final max = data.fold<double>(0, (m, e) => valueBuilder(e) > m ? valueBuilder(e) : m); return Card(child: Padding(padding: const EdgeInsets.all(16), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text(title, style: const TextStyle(fontWeight: FontWeight.bold)), const SizedBox(height: 12), ...data.map((e) => Padding(padding: const EdgeInsets.only(bottom: 8), child: Row(children: [SizedBox(width: 42, child: Text(e.label)), Expanded(child: LinearProgressIndicator(value: max == 0 ? 0 : valueBuilder(e) / max)), const SizedBox(width: 8), Text(valueBuilder(e).toStringAsFixed(0))])))]))); } }
